using System;
using System.Threading.Tasks;

namespace Zongsoft.Externals.Garnet.Tests;

//插件上下文和 Main 插件含有进程级状态，每个场景使用独立入口。
internal static class TestProgram
{
	public static bool IsProbe { get; private set; }

	public static async Task<int> Main(string[] args)
	{
		if(args.Length != 2 || args[0] != "--garnet-probe")
			return AutoGenerated.XunitAutoGeneratedEntryPoint.Main(args);

		try
		{
			IsProbe = true;
			var tests = new GarnetServerTests();

			switch(args[1])
			{
				case nameof(GarnetServerTests.PluginBindingMatchesListeningServer):
					await tests.PluginBindingMatchesListeningServer();
					break;
				case nameof(GarnetServerTests.SelectionAndLifecycleUseOnlyNamedSettings):
					await tests.SelectionAndLifecycleUseOnlyNamedSettings();
					break;
				case nameof(GarnetServerTests.InvalidSettingsNeverStartListener):
					await tests.InvalidSettingsNeverStartListener();
					break;
				case nameof(GarnetServerTests.CancellationDoesNotOpenListener):
					await tests.CancellationDoesNotOpenListener();
					break;
				case nameof(GarnetServerTests.FailedStartCanRetryAfterPortIsReleased):
					await tests.FailedStartCanRetryAfterPortIsReleased();
					break;
				case nameof(GarnetServerTests.Ipv6ListenerRespondsAndReleasesPort):
					await tests.Ipv6ListenerRespondsAndReleasesPort();
					break;
				case nameof(GarnetServerTests.PasswordAuthenticationRejectsAnonymousRequestsAndAcceptsAuthenticatedPing):
					await tests.PasswordAuthenticationRejectsAnonymousRequestsAndAcceptsAuthenticatedPing();
					break;
				case nameof(GarnetServerTests.TlsUsesApplicationRelativeCertificateAndFriendlyAliases):
					await tests.TlsUsesApplicationRelativeCertificateAndFriendlyAliases();
					break;
				default:
					return 2;
			}

			Console.WriteLine($"Completed:{args[1]}");
			return 0;
		}
		catch(Exception exception)
		{
			Console.Error.WriteLine(exception);
			return 1;
		}
	}
}
